class Solution {

    public ListNode reverseList(ListNode head) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (
            ListNode cur = head;
            cur != null;
            cur = cur.next
        ) stack.push(cur.val);
        for (ListNode cur = head; cur != null; cur = cur.next) cur.val =
            stack.pop(); // last value first
        return head;
    }
}

