class Solution {

    public void reorderList(ListNode head) {
        if (head == null || head.next == null) return;
        ListNode slow = head,
            fast = head.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode second = slow.next;
        slow.next = null; // split into two lists
        ListNode prev = null;
        while (second != null) {
            // reverse second half
            ListNode nx = second.next;
            second.next = prev;
            prev = second;
            second = nx;
        }
        ListNode first = head;
        second = prev;
        while (second != null) {
            // weave; second is never longer than first
            ListNode t1 = first.next,
                t2 = second.next;
            first.next = second;
            second.next = t1;
            first = t1;
            second = t2;
        }
    }
}

