class Solution {

    public Node copyRandomList(Node head) {
        if (head == null) return null;
        for (Node c = head; c != null; c = c.next.next) {
            // 1. interleave
            Node copy = new Node(c.val);
            copy.next = c.next;
            c.next = copy;
        }
        for (Node c = head; c != null; c = c.next.next) {
            // 2. randoms: copy of X is X.next
            if (c.random != null) c.next.random = c.random.next;
        }
        Node newHead = head.next;
        for (Node c = head; c != null; c = c.next) {
            // 3. unzip
            Node copy = c.next;
            c.next = copy.next; // restore original
            if (copy.next != null) copy.next = copy.next.next;
        }
        return newHead;
    }
}

