class Solution {

    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        java.math.BigInteger a = toNum(l1),
            b = toNum(l2),
            sum = a.add(b);
        String s = sum.toString();
        ListNode dummy = new ListNode(0),
            tail = dummy;
        for (int i = s.length() - 1; i >= 0; i--) {
            // ones digit first
            tail.next = new ListNode(s.charAt(i) - '0');
            tail = tail.next;
        }
        return dummy.next;
    }

    private java.math.BigInteger toNum(ListNode l) {
        StringBuilder sb = new StringBuilder();
        for (ListNode c = l; c != null; c = c.next) sb.append(c.val);
        return new java.math.BigInteger(sb.reverse().toString()); // most significant first
    }
}

