class LRUCache {

    private final int capacity;
    private final List<int[]> list = new ArrayList<>(); // {key, value}, index 0 = least recent

    public LRUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i)[0] == key) {
                int[] e = list.remove(i);
                list.add(e); // now most recent
                return e[1];
            }
        }
        return -1;
    }

    public void put(int key, int value) {
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i)[0] == key) {
                list.remove(i);
                break;
            }
        }
        list.add(new int[] { key, value });
        if (list.size() > capacity) list.remove(0); // evict least recent
    }
}

