class LRUCache {

    private static class DNode {

        int key, val;
        DNode prev, next;

        DNode(int k, int v) {
            key = k;
            val = v;
        }
    }

    private final int capacity;
    private final Map<Integer, DNode> map = new HashMap<>();

    private final DNode head = new DNode(0, 0),
        tail = new DNode(0, 0); // dummies

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    private void remove(DNode n) {
        // unlink in O(1)
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }

    private void addFront(DNode n) {
        // insert right after head (most recent)
        n.next = head.next;
        n.prev = head;
        head.next.prev = n;
        head.next = n;
    }

    public int get(int key) {
        DNode n = map.get(key);
        if (n == null) return -1;
        remove(n);
        addFront(n);
        return n.val;
    }

    public void put(int key, int value) {
        DNode n = map.get(key);
        if (n != null) {
            n.val = value;
            remove(n);
            addFront(n);
            return;
        }
        n = new DNode(key, value);
        map.put(key, n);
        addFront(n);
        if (map.size() > capacity) {
            DNode lru = tail.prev; // least recent
            remove(lru);
            map.remove(lru.key); // node stores key so we can clean the map
        }
    }
}

