class LRUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.map = new Map();
        this.head = new DNode(0, 0);
        this.tail = new DNode(0, 0);

        this.head.next = this.tail;
        this.tail.prev = this.head;
    }
    _remove(n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }
    _addFront(n) {
        n.next = this.head.next;
        n.prev = this.head;
        this.head.next.prev = n;
        this.head.next = n;
    }
    get(key) {
        const n = this.map.get(key);
        if (!n) return -1;
        this._remove(n);
        this._addFront(n);
        return n.val;
    }
    put(key, value) {
        let n = this.map.get(key);
        if (n) {
            n.val = value;
            this._remove(n);
            this._addFront(n);
            return;
        }
        n = new DNode(key, value);
        this.map.set(key, n);
        this._addFront(n);
        if (this.map.size > this.capacity) {
            const lru = this.tail.prev;
            this._remove(lru);
            this.map.delete(lru.key);
        }
    }
}

