class Solution {

    Node flatten(Node root) {
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) ->
            Integer.compare(a.data, b.data)
        );
        for (Node col = root; col != null; col = col.next) pq.offer(
            col
        );
        Node dummy = new Node(0),
            t = dummy;
        while (!pq.isEmpty()) {
            Node node = pq.poll();
            if (node.bottom != null) pq.offer(node.bottom); // next candidate from same column
            t.bottom = node;
            t = node;
            t.next = null;
        }
        t.bottom = null;
        return dummy.bottom;
    }
}

