function flatten(root) {
    // tiny binary heap ordered by node.data
    const h = [];
    const less = (i, j) => h[i].data < h[j].data;
    const swap = (i, j) => {
        [h[i], h[j]] = [h[j], h[i]];
    };
    const push = (x) => {
        h.push(x);
        for (
            let i = h.length - 1;
            i > 0 && less(i, (i - 1) >> 1);
            i = (i - 1) >> 1
        )
            swap(i, (i - 1) >> 1);
    };
    const pop = () => {
        const top = h[0],
            last = h.pop();
        if (h.length) {
            h[0] = last;
            for (let i = 0; ;) {
                let m = i;
                const l = 2 * i + 1,
                    r = l + 1;
                if (l < h.length && less(l, m)) m = l;
                if (r < h.length && less(r, m)) m = r;

                if (m === i) break;
                swap(i, m);
                i = m;
            }
        }
        return top;
    };
    for (let col = root; col; col = col.next) push(col);
    const dummy = new Node(0);
    let t = dummy;
    while (h.length) {
        const node = pop();
        if (node.bottom) push(node.bottom);
        t.bottom = node;
        t = node;
        t.next = null;
    }
    t.bottom = null;
    return dummy.bottom;
}
